-- ============================================
-- Реестр кортов Кыргызстана вместо тестовых
-- ============================================
--
-- 31 корт из файла Tennis_Courts_Kyrgyzstan.xlsx (данные собраны
-- 20.08.2026). Цены не переносим: в файле у большинства объектов
-- расхождения между источниками — их проставит вручную админ.
-- Фотографии тоже вставляются вручную, ссылки из файла не трогаем.
--
-- Каждый корт — отдельная запись: их можно править по одному
-- в админке.

BEGIN;

-- 1. За тестовые корты держатся другие таблицы: турниры ссылаются через
--    court_id, баттлы — через proposed_court_id. Перечислять их руками
--    ненадёжно: одно поле уже нашлось не там, где ожидалось. Поэтому
--    обходим все внешние ключи, какие есть в базе, и отвязываем разом
DO $$
DECLARE
    r RECORD;
BEGIN
    -- Обязательную ссылку в NULL не поставить: если такая есть, честно
    -- останавливаемся с понятным сообщением, а не падаем на DELETE
    FOR r IN
        SELECT src.relname AS tbl, att.attname AS col
        FROM pg_constraint c
        JOIN pg_class src ON src.oid = c.conrelid
        JOIN pg_class dst ON dst.oid = c.confrelid
        JOIN pg_attribute att ON att.attrelid = c.conrelid AND att.attnum = c.conkey[1]
        WHERE c.contype = 'f' AND dst.relname = 'courts' AND att.attnotnull
    LOOP
        RAISE EXCEPTION 'На корты ссылается обязательное поле %.% — сначала решите, что делать с этими записями', r.tbl, r.col;
    END LOOP;

    -- Всё остальное отвязываем
    FOR r IN
        SELECT src.relname AS tbl, att.attname AS col
        FROM pg_constraint c
        JOIN pg_class src ON src.oid = c.conrelid
        JOIN pg_class dst ON dst.oid = c.confrelid
        JOIN pg_attribute att ON att.attrelid = c.conrelid AND att.attnum = c.conkey[1]
        WHERE c.contype = 'f' AND dst.relname = 'courts' AND NOT att.attnotnull
    LOOP
        EXECUTE format('UPDATE public.%I SET %I = NULL WHERE %I IS NOT NULL',
                       r.tbl, r.col, r.col);
    END LOOP;
END $$;

-- 2. Чистим тестовые корты
DELETE FROM courts;

-- 3. Заносим реестр

