  ('tennis-bishkek-trener-gruppy', '«Теннис Бишкек» (@tennis.bishkek) — тренер/группы', NULL, 'Бишкек', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Аккаунт тренера/группы по большому теннису в Бишкеке.', 'Аккаунт тренера/группы по большому теннису в Бишкеке. Не значится ни в 2ГИС, ни в гидах kaktus.media и sxodim — типичный случай «только Instagram». На каком корте проводятся занятия, не установлено.

Услуги: Набор взрослых в группу большого тенниса (подтверждено текстом рилса)

НАЙДЕНО ТОЛЬКО В INSTAGRAM. Требует контакта в директ для уточнения площадки, цен и расписания.', '[]'::jsonb, false, false, 0);

-- Курортный отель «Каприз Иссык-Куль»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('kapriz-issyk-kul-resort-hotel', 'Курортный отель «Каприз Иссык-Куль»', 'Kapriz Issyk-Kul Resort Hotel', 'Иссык-Куль', 'ул. Кыргызская', '38', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Бактуу-Долоноту, ул. Кыргызская, 38', 42.643462, 77.154898, '+996 777 90 51 75', NULL, 'https://www.google.com/maps/search/?api=1&query=42.643462,77.154898', 'https://2gis.kg/bishkek/firm/70000001027789182', 'Крупнейший теннисный объект северного берега Иссык-Куля.', 'Крупнейший теннисный объект северного берега Иссык-Куля. На официальном сайте отеля есть отдельная страница услуги «Теннисные корты грунтовые (clay court)», а на кортах регулярно проходят международные и детские турниры по большому теннису — в том числе серия международных турниров, о которой писала спортивная пресса Кыргызстана. Корты грунтовые, открытые, работают в тёплый сезон. Точное число кортов и прайс на сайте не опубликованы.

Услуги: Проводятся детские и международные турниры по большому теннису (Кубок ЦО «Каприз»); заявлены спортивные сборы и лагерь. Прокат инвентаря/тренер не подтверждены документально.

Сезонность: летний сезон (грунт, открытые корты). Доступ: скорее всего платно и для гостей, и для внешних игроков — во время турниров территория открыта для участников. Состояние: судя по проведению турниров 2024–2026 гг., корты в рабочем состоянии. ВАЖНО: сайт kaprizissykkul.kg отдаёт 404/редиректы автоматическим фетчерам, поэтому текст страницы кортов не удалось прочитать напрямую — данные взяты из заголовка страницы в поисковой выдаче и из зеркал.', '[{"type": "outdoor", "count": "", "surface": "clay", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Центр отдыха «Карвен Четыре Сезона»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('karven-four-seasons', 'Центр отдыха «Карвен Четыре Сезона»', 'Karven Four Seasons', 'Иссык-Куль', 'ул. Нурдоолот', '1г', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Бает/Чок-Тал, ул. Нурдоолот, 1г', 42.605186, 76.937045, '+996 555 53 53 90', NULL, 'https://www.google.com/maps/search/?api=1&query=42.605186,76.937045', 'https://2gis.kg/bishkek/firm/70000001027954842', 'Самый крупный теннисный кластер на Иссык-Куле: четыре открытых корта с искусственной травой и один крытый корт в составе спортивного комплекса.', 'Самый крупный теннисный кластер на Иссык-Куле: четыре открытых корта с искусственной травой и один крытый корт в составе спортивного комплекса. Здесь исторически проводился любительский турнир «Karven Open». Работают профессиональные инструкторы по теннису, рядом — 2 корта для пиклбола, футбольные поля, боулинг и 25-метровый бассейн.

Услуги: Профессиональные инструкторы тенниса («К Вашим услугам профессиональные инструкторы тенниса и плавания»); спорткомплекс пригоден для проведения соревнований по теннису и настольному теннису; 2 корта для пиклбола. Прокат ракеток явно не заявлен на текущем сайте.

Крытый корт делает объект всесезонным — единственный такой на озере наряду с заявленным крытым кортом «Ак-Марал». Доступ: преимущественно для гостей центра отдыха, но спорткомплекс сдаётся под сборы/соревнования. Прайс на теннис на официальном сайте не опубликован. ВНИМАНИЕ: старый агрегатор Advantour приводит устаревшие данные (1 крытый + 1 открытый, $24/час крытый, $12/час открытый, тренер $12/час) — эти цифры расходятся с текущим сайтом и, вероятно, устарели.', '[{"type": "outdoor", "count": 4, "surface": "grass", "price": "", "partner": false}, {"type": "indoor", "count": 1, "surface": "grass", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Отель «Акун Иссык-Куль»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('akun-issyk-kul-hotel', 'Отель «Акун Иссык-Куль»', 'Akun Issyk-Kul Hotel', 'Иссык-Куль', 'ул. Жусупа Абдрахманова', '341Б', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Кара-Ой, ул. Жусупа Абдрахманова (Советская), 341Б', NULL, NULL, '+996 775 99 95 55', NULL, 'https://www.google.com/maps/search/?api=1&query=%D0%90%D0%BA%D1%83%D0%BD+%D0%98%D1%81%D1%81%D1%8B%D0%BA-%D0%9A%D1%83%D0%BB%D1%8C+%D0%9A%D0%B0%D1%80%D0%B0-%D0%9E%D0%B9', 'https://2gis.kg/bishkek/firm/70000001027788878', 'Один из двух главных турнирных теннисных объектов Иссык-Куля.', 'Один из двух главных турнирных теннисных объектов Иссык-Куля. Отель заявляет открытый теннисный корт (отдельный пост на официальной странице Facebook «Открытый теннисный корт в отеле Акун Иссык-Куль»), а пресса описывает его как «международный теннисный центр», корты которого «соответствуют международным требованиям». В августе 2026 здесь третий год подряд прошёл международный любительский турнир «Акун», собравший более 40 игроков из Кыргызстана и Казахстана.

Услуги: Теннис отнесён к платным услугам отеля. Ежегодный международный любительский турнир «Акун» (2024, 2025, 2026), директор турнира — Асель Макаева; категории: женская/мужская пара, микст (Tour и Masters).

Сезонность: летняя (открытый корт). Настольный теннис в отеле есть отдельно — путаницы в источниках нет, оба вида перечислены раздельно. Покрытие и число кортов ни в одном источнике не указаны; официальный сайт aik.kg зациклен на редиректе http/https и не читается автоматически. Формулировка «международный теннисный центр» может быть маркетинговой — фактическое число кортов надо уточнять по телефону.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Курортный отель «Марко Поло»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('marco-polo-resort-hotel', 'Курортный отель «Марко Поло»', 'Marco Polo Resort Hotel', 'Иссык-Куль', 'с. Боз-Бешик', NULL, 'Джети-Огузский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Джети-Огузский р-н, с. Боз-Бешик, участок Ыссык-Кол, 1а (южный берег)', 42.460918, 77.941162, '+996 702 55 55 95', NULL, 'https://www.google.com/maps/search/?api=1&query=42.460918,77.941162', 'https://2gis.kg/bishkek/firm/70000001027818396', 'Единственный на южном берегу Иссык-Куля корт с полностью опубликованным прайсом.', 'Единственный на южном берегу Иссык-Куля корт с полностью опубликованным прайсом. Один открытый корт с искусственной травой, профессиональным освещением и усиленным ограждением. Аренда — 500 сом/час, прокат ракетки — 150 сом/сутки. Сайт отеля прямо оговаривает, что речь идёт о большом теннисе («большой теннис занял позицию... одного из наиболее престижных видов спорта»).

Услуги: Прокат теннисной ракетки — 150 сом/сутки; профессиональное освещение для вечерней игры; усиленное ограждение корта по периметру. Тренер не заявлен.

Сезонность: открытый корт, но наличие освещения расширяет вечернее время игры. Доступ: платно, по прайсу — вероятно, доступно и не проживающим, но это не оговорено. Отель расположен в Джети-Огузском районе (Боз-Бешик), не в Чолпон-Ате.', '[{"type": "outdoor", "count": 1, "surface": "grass", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- AZURE Sport Resort
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('azur-sport-rezort', 'AZURE Sport Resort', '«АЗУР Спорт Резорт»', 'Иссык-Куль', 'ул. Сегетту', '22', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Булан-Соготту, ул. Сегетту, 22', NULL, NULL, '+996 770 07 21 11', 'hotel@azure.kg', 'https://www.google.com/maps/search/?api=1&query=AZURE+Sport+Resort+%D0%91%D1%83%D0%BB%D0%B0%D0%BD-%D0%A1%D0%BE%D0%B3%D0%BE%D1%82%D1%82%D1%83', 'https://2gis.kg/bishkek/firm/70000001027756074', 'Спортивно-ориентированный отель в Булан-Соготту с собственным теннисным кортом с искусственным покрытием.', 'Спортивно-ориентированный отель в Булан-Соготту с собственным теннисным кортом с искусственным покрытием. Отель позиционирует себя как круглогодичный, теннис входит в список платных услуг наряду с баскетболом и дартсом. Число кортов — один («собственный теннисный корт»).

Услуги: Теннис отнесён к ПЛАТНЫМ услугам отеля. Рядом — баскетбольная площадка, дартс, 25-метровый крытый бассейн (5 дорожек), тренажёрный зал, воркаут-зона.

Сезонность: корт открытый, поэтому фактически летний, несмотря на круглогодичную работу отеля. Цена не опубликована — уточнять по телефону. Настольный теннис на сайте отдельно не заявлен, но формулировка «теннисный корт с искусственным покрытием» однозначно указывает на большой теннис.', '[{"type": "outdoor", "count": 1, "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Центр отдыха «Карвен Иссык-Куль»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('karven-issyk-kul', 'Центр отдыха «Карвен Иссык-Куль»', 'Karven Issyk-Kul', 'Иссык-Куль', 'ул. Ленина', '2/5', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Булан-Соготту, ул. Ленина, 2/5', NULL, NULL, '+996 772 50 23 10', 'natasha@ak-sai.com', 'https://www.google.com/maps/search/?api=1&query=%D0%9A%D0%B0%D1%80%D0%B2%D0%B5%D0%BD+%D0%98%D1%81%D1%81%D1%8B%D0%BA-%D0%9A%D1%83%D0%BB%D1%8C+%D0%91%D1%83%D0%BB%D0%B0%D0%BD-%D0%A1%D0%BE%D0%B3%D0%BE%D1%82%D1%82%D1%83', 'https://2gis.kg/bishkek/firm/70000001027759168', 'Центр отдыха в Булан-Соготту, в 20 км от Чолпон-Аты.', 'Центр отдыха в Булан-Соготту, в 20 км от Чолпон-Аты. Два независимых источника указывают «открытый теннисный корт и зал настольного тенниса» — то есть большой и настольный теннис разведены явно. Корт бесплатен для проживающих. Комплекс работает круглогодично, 45 номеров.

Услуги: Бесплатно для проживающих гостей. Отдельно — зал настольного тенниса, универсальная спортплощадка (баскетбол/волейбол/мини-футбол), 2 бильярдных зала.

Сезонность: открытый корт — летний. Доступ: бесплатно для гостей ЦО; для внешних посетителей условия неизвестны. Покрытие и состояние корта нигде не описаны — риск, что это старая асфальтовая/бетонная площадка. ВНИМАНИЕ: прямых контактов самого ЦО найти не удалось, приведены телефоны туроператоров-агентов.', '[{"type": "outdoor", "count": 1, "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Пансионат «Меридиан»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('meridian', 'Пансионат «Меридиан»', 'Meridian', 'Иссык-Куль', 'ул. Сегетту', '2', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Булан-Соготту, ул. Сегетту, 2', NULL, NULL, '+996 505 58 16 81', 'info@issykkul.biz', 'https://www.google.com/maps/search/?api=1&query=%D0%9C%D0%B5%D1%80%D0%B8%D0%B4%D0%B8%D0%B0%D0%BD+%D0%BF%D0%B0%D0%BD%D1%81%D0%B8%D0%BE%D0%BD%D0%B0%D1%82+%D0%91%D1%83%D0%BB%D0%B0%D0%BD-%D0%A1%D0%BE%D0%B3%D0%BE%D1%82%D1%82%D1%83', 'https://2gis.kg/bishkek/firm/70000001027755601', 'Небольшой пансионат на 200 мест в Булан-Соготту, в 20 км от Чолпон-Аты, на участке 5,36 га.', 'Небольшой пансионат на 200 мест в Булан-Соготту, в 20 км от Чолпон-Аты, на участке 5,36 га. В прайсе платных услуг большой теннис и настольный теннис указаны раздельно и с разными ценами — 400 и 200 сом/час соответственно, что снимает вопрос о путанице. Территория с розарием и садом, собственная пляжная зона 1,18 га.

Услуги: Прайс платных услуг: «Теннисный корт 400 сом/час, Настольный теннис 200 сом/час, Бильярд 400 сомов/час, Сауна+бассейн 1500 сом/час»; также виндсёрфинг, SUP, тренажёрный зал.

Сезонность: летняя. Доступ: платно, вероятно и для гостей, и для сторонних. Покрытие и количество кортов не указаны; состояние корта неизвестно. ВНИМАНИЕ: приведённые контакты принадлежат агрегатору issykkul.biz, а не пансионату — собственных контактов «Меридиана» найти не удалось.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Санаторий «Иссык-Куль Аврора»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('issyk-kul-aurora-sanatorium', 'Санаторий «Иссык-Куль Аврора»', 'Issyk-Kul Aurora Sanatorium', 'Иссык-Куль', 'ул. Ленина', '2Б', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Булан-Соготту, ул. Ленина, 2Б', NULL, NULL, '+996 772 50 23 10', 'natasha@ak-sai.com', 'https://www.google.com/maps/search/?api=1&query=%D0%A1%D0%B0%D0%BD%D0%B0%D1%82%D0%BE%D1%80%D0%B8%D0%B9+%D0%98%D1%81%D1%81%D1%8B%D0%BA-%D0%9A%D1%83%D0%BB%D1%8C-%D0%90%D0%B2%D1%80%D0%BE%D1%80%D0%B0', 'https://2gis.kg/bishkek/firm/70000001044694649', 'Классический советский санаторий на 47 га парковой территории в Булан-Соготту, в 20 км от Чолпон-Аты и 270 км от Бишкека.', 'Классический советский санаторий на 47 га парковой территории в Булан-Соготту, в 20 км от Чолпон-Аты и 270 км от Бишкека. В перечне платных услуг «теннисный корт» и «настольный теннис» указаны как две разные позиции. Собственный песчаный пляж в 300 м от главного корпуса.

Услуги: Теннисный корт и настольный теннис отнесены к платным услугам (перечислены раздельно). Бесплатно — мини-футбол и спортплощадки; платно — тренажёрный зал, сауна, бильярд.

Сезонность: летняя (открытый корт). Доступ: платно для отдыхающих. Покрытие, количество и состояние корта нигде не описаны — для санатория такого возраста высок риск, что корт представляет собой старую асфальтовую площадку. Собственных контактов санатория найти не удалось.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Пансионат «Мурас» (бывш. «Витязь»)
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('muras', 'Пансионат «Мурас» (бывш. «Витязь»)', 'Muras', 'Иссык-Куль', 'ул. Эрденеева', '52', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Чок-Тал, ул. Эрденеева, 52 (1,5 км от аэропорта Иссык-Куль)', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=%D0%9C%D1%83%D1%80%D0%B0%D1%81+%D0%BF%D0%B0%D0%BD%D1%81%D0%B8%D0%BE%D0%BD%D0%B0%D1%82+%D0%A7%D0%BE%D0%BA-%D0%A2%D0%B0%D0%BB', 'https://2gis.kg/bishkek/firm/70000001027820933', 'Пансионат в Чок-Тале (бывший «Витязь»), в 1,5 км от аэропорта Иссык-Куль.', 'Пансионат в Чок-Тале (бывший «Витязь»), в 1,5 км от аэропорта Иссык-Куль. Заявлен открытый теннисный корт с искусственным покрытием, отдельно — настольный теннис. Размещение в коттеджах и студиях, собственный пляж с пирсом, охраняемая парковка на 100 мест.

Услуги: Настольный теннис указан отдельно как вечернее развлечение. Бесплатная уличная воркаут-зона с тренажёрами, детские площадки, собственный пляж с пирсом.

Сезонность: летняя. Данные о цене корта отсутствуют. ВНИМАНИЕ: контакты не приводятся — все найденные телефоны принадлежат казахстанским туроператорам-посредникам (+7 776 756-00-89 и т. п.), а не пансионату; выдумывать номер объекта я не стал.', '[{"type": "outdoor", "count": 1, "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Пансионат «Солнышко» (VIP-городок)
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('solnyshko-vip', 'Пансионат «Солнышко» (VIP-городок)', 'Solnyshko VIP', 'Иссык-Куль', 'ул. Эрденеева', '44а/40', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Чок-Тал, ул. Эрденеева, 44а/40 (30 км от Чолпон-Аты, 220 км от Бишкека)', NULL, NULL, '+996 552 15 21 39', NULL, 'https://www.google.com/maps/search/?api=1&query=%D0%A1%D0%BE%D0%BB%D0%BD%D1%8B%D1%88%D0%BA%D0%BE+VIP+%D0%A7%D0%BE%D0%BA-%D0%A2%D0%B0%D0%BB', 'https://2gis.kg/bishkek/firm/70000001059755095', 'VIP-городок из коттеджей в Чок-Тале.', 'VIP-городок из коттеджей в Чок-Тале. Два независимых каталога (issykkul.biz и issykkul.com) указывают «два теннисных корта» с прокатом спортивного инвентаря, при этом настольный теннис в списке не фигурирует, что говорит в пользу большого тенниса. Территория с 25-метровым бассейном с минеральной водой, пляж в 100 м.

Услуги: «Два теннисных корта, прокат спортивного и пляжного инвентаря» — прокат инвентаря подтверждён. 25-метровый бассейн с минеральной водой, спа, конференц-услуги.

Сезонность: летняя. ВАЖНО: страница issykkul.biz содержит прайс 2013 года — описание удобств тоже может быть устаревшим на 10+ лет; вероятность, что корты в плохом состоянии или уже застроены, значительна. Цену аренды кортов ни один источник не даёт. Телефоны — общие для каталога issykkul.com, проверить принадлежность объекту не удалось.', '[{"type": "outdoor", "count": 2, "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Центр отдыха «Ак-Марал»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('ak-maral', 'Центр отдыха «Ак-Марал»', 'Ak-Maral', 'Иссык-Куль', 'ул. Ак-Марал', '1/1', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Бает, ул. Ак-Марал, 1/1 (северный берег)', NULL, NULL, '+996 772 50 23 10', 'natasha@ak-sai.com', 'https://www.google.com/maps/search/?api=1&query=%D0%90%D0%BA-%D0%9C%D0%B0%D1%80%D0%B0%D0%BB+%D0%BF%D0%B0%D0%BD%D1%81%D0%B8%D0%BE%D0%BD%D0%B0%D1%82+%D0%98%D1%81%D1%81%D1%8B%D0%BA-%D0%9A%D1%83%D0%BB%D1%8C', 'https://2gis.kg/bishkek/firm/70000001027778190', 'Центр отдыха в селе Бает на северном берегу.', 'Центр отдыха в селе Бает на северном берегу. Один каталог прямо указывает «теннисные корты (открытый и крытый)», второй подтверждает наличие теннисного корта без уточнения типа. Настольный теннис в списках не упоминается. На территории также открытый и зимний крытый бассейны, фитнес-клуб, бильярд.

Услуги: Тренажёрный зал, баскетбольная и волейбольная площадки, открытый и зимний закрытый бассейны, спа-салон, водные развлечения.

Сезонность: если крытый корт существует, объект всесезонный; в противном случае — летний. Крытый корт на Иссык-Куле — редкость, поэтому это заявление требует проверки на месте: возможно, речь о спортзале с разметкой, а не о полноценном крытом корте. Цена не опубликована. Контакты — туроператора-агента, не самого ЦО.', '[{"type": "indoor", "count": "", "surface": "", "price": "", "partner": false}, {"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Пансионат «Три Короны»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('tri-korony', 'Пансионат «Три Короны»', 'Tri Korony', 'Иссык-Куль', 'аллея Айтматова', '3/1', NULL, NULL, 'Кыргызстан, Иссык-Кульская обл., г. Чолпон-Ата, аллея Айтматова, 3/1', 42.635865, 77.089925, '+996 558 08 50 02', '3koronykg@mail.ru', 'https://www.google.com/maps/search/?api=1&query=42.635865,77.089925', 'https://2gis.kg/cholpon-ata/firm/70000001027860639', 'Пансионат в самой Чолпон-Ате, на аллее Айтматова.', 'Пансионат в самой Чолпон-Ате, на аллее Айтматова. На официальном сайте в списке спортивных объектов теннисный корт и настольный теннис указаны как две разные позиции, что подтверждает наличие именно большого тенниса. Также собственный пляж с пирсом 150 м, открытый бассейн, мини-футбол, баскетбол и волейбол.

Услуги: Отдельно перечислены настольный теннис, волейбольная и баскетбольная площадки, мини-футбольное поле, тренажёрный зал, открытая фитнес-зона, бассейн 15×8 м, пирс 150 м.

Сезонность: летняя. Покрытие, количество кортов и цена на сайте не опубликованы; вероятно, корт доступен гостям бесплатно или за небольшую плату, но это не подтверждено. Состояние корта не проверено.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Baytur Resort & SPA
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('baytur-rezort-end-spa', 'Baytur Resort & SPA', '«Байтур Резорт энд СПА»', 'Иссык-Куль', 'с. Бостери', NULL, 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Бостери, 55-й квартал, 114Б/2', 42.647988, 77.21385, '+996 551 99 00 00', 'Reservation.issykkul@baytur.kg', 'https://www.google.com/maps/search/?api=1&query=42.647988,77.21385', 'https://2gis.kg/bishkek/firm/70000001062985592', 'Крупный современный пансионат в Бостери.', 'Крупный современный пансионат в Бостери. На официальном сайте в перечне удобств указан «Большой теннис», а раздел «Спорт» упоминает теннисные площадки «международных стандартов». Tripadvisor также относит объект к отелям Иссык-Кульской области с теннисным кортом.

Услуги: Заявлено, что «футбольные и теннисные площадки» соответствуют международным стандартам и «просторные для комфортных тренировок». 2 тренажёрных зала, крытый и открытый бассейны, банный комплекс, джакузи.

ПРОТИВОРЕЧИЕ В ИСТОЧНИКАХ: Expedia/Hotels.com в списке удобств Baytur теннисный корт НЕ указывают вовсе, перечисляя только бассейны, спа и пляж. Формулировки собственного сайта («площадки, соответствующие международным стандартам») звучат маркетингово-аспирационно. Количество кортов, покрытие и цена нигде не опубликованы. Требуется проверка звонком.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Санаторий «Кыргызское взморье»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('kyrgyzskoe-vzmorye', 'Санаторий «Кыргызское взморье»', 'Kyrgyzskoe Vzmorye', 'Иссык-Куль', 'аллея Акматова', '4а', 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Бостери, аллея Акматова, 4а', NULL, NULL, '+996 772 50 23 10', 'natasha@ak-sai.com', 'https://www.google.com/maps/search/?api=1&query=%D0%9A%D1%8B%D1%80%D0%B3%D1%8B%D0%B7%D1%81%D0%BA%D0%BE%D0%B5+%D0%B2%D0%B7%D0%BC%D0%BE%D1%80%D1%8C%D0%B5+%D0%91%D0%BE%D1%81%D1%82%D0%B5%D1%80%D0%B8', 'https://2gis.kg/bishkek/firm/70000001027811417', 'Старый крупный санаторий советского типа в Бостери.', 'Старый крупный санаторий советского типа в Бостери. В развёрнутом списке удобств «теннисные корты» и «настольный теннис» перечислены как разные позиции: «футбольная и волейбольная площадка, настольный теннис, бильярдная, дискотека, бассейн, сауна, тренажерный зал, солярий, библиотека, кинозал, зимний сад, фитобар, теннисные корты, дискобар, казино, интернет-клуб, фитнес-центр».

Услуги: Настольный теннис указан отдельной позицией. Также футбольная и волейбольная площадки, бильярд, бассейн, сауна, тренажёрный зал, фитнес-центр, солярий, кинозал.

ВЫСОКИЙ РИСК УСТАРЕВШЕЙ ИНФОРМАЦИИ: перечень удобств выглядит как унаследованный от советского описания санатория (казино, интернет-клуб, зимний сад) и почти наверняка частично не соответствует действительности. Корты, если они существуют, вероятно в изношенном состоянии. Сезонность: летняя. Цена и покрытие неизвестны.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Центр отдыха «Солемар»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('solemar', 'Центр отдыха «Солемар»', 'Solemar', 'Иссык-Куль', 'с. Корумду', NULL, 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Корумду (276 км от Бишкека, северный берег)', NULL, NULL, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=%D0%A1%D0%BE%D0%BB%D0%B5%D0%BC%D0%B0%D1%80+%D0%9A%D0%BE%D1%80%D1%83%D0%BC%D0%B4%D1%83+%D0%98%D1%81%D1%81%D1%8B%D0%BA-%D0%9A%D1%83%D0%BB%D1%8C', NULL, 'Центр отдыха в селе Корумду восточнее Бостери.', 'Центр отдыха в селе Корумду восточнее Бостери. В списке удобств указаны «теннисные корты» во множественном числе, при этом настольный теннис отдельно не упоминается. На территории аквапарк, крытый и открытый бассейны, спа, собственный пляж со 110-метровым пирсом.

Услуги: Спортивные площадки, караоке, бильярд, 2 сауны, крытый и открытый бассейны, аквапарк, анимация, спа.

Сезонность: летняя. Ни количество, ни покрытие, ни цена не указаны. ВНИМАНИЕ: собственный сайт и карточку 2ГИС для объекта найти не удалось; телефоны в источнике (+7 707 990-10-42) принадлежат казахстанскому туроператору, поэтому в контакты они не внесены. Отсутствие упоминания настольного тенниса не гарантирует, что «теннисные корты» — большой теннис.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Центр отдыха «Радуга»
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('raduga', 'Центр отдыха «Радуга»', 'Raduga', 'Иссык-Куль', 'с. Сары-Ой', NULL, 'Иссык-Кульский район', NULL, 'Кыргызстан, Иссык-Кульская обл., Иссык-Кульский р-н, с. Сары-Ой (14 км от Чолпон-Аты)', NULL, NULL, '+996 552 39 40 40', NULL, 'https://www.google.com/maps/search/?api=1&query=%D0%A0%D0%B0%D0%B4%D1%83%D0%B3%D0%B0+%D1%86%D0%B5%D0%BD%D1%82%D1%80+%D0%BE%D1%82%D0%B4%D1%8B%D1%85%D0%B0+%D0%A1%D0%B0%D1%80%D1%8B-%D0%9E%D0%B9', NULL, 'Крупный центр отдыха на 29 га в селе Сары-Ой, в 14 км от Чолпон-Аты.', 'Крупный центр отдыха на 29 га в селе Сары-Ой, в 14 км от Чолпон-Аты. Ранее на официальном сайте существовала отдельная страница фотогалереи «Теннисный корт» (raduga.kg/about-resort-center/photo-gallery/94-tennis-court.html), а каталог issykkul.biz по-прежнему указывает «теннисный корт» в перечне удобств.

Услуги: 2 ресторана, 4 бара, 4 кафе, спа-центр, 2 бассейна (крытый и открытый), сауна и хамам, бильярд, аквапарк, 2 конференц-зала, песчаный пляж 1000 м с тремя пирсами.

КРАСНЫЙ ФЛАГ: страница «Теннисный корт» на официальном сайте сейчас отдаёт 404, а актуальная версия raduga.kg в перечне услуг теннис вообще не упоминает (только спа, бани, сауны, бассейны, водные развлечения, рестораны, конференц-услуги). Вероятно, корт демонтирован, застроен или выведен из эксплуатации. Требуется проверка звонком по +996 552 39 40 40.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Теннисный корт (безымянный объект 2ГИС), Чолпон-Ата
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('unnamed-tennis-court-cholpon-ata', 'Теннисный корт (безымянный объект 2ГИС), Чолпон-Ата', 'Unnamed tennis court, Cholpon-Ata', 'Иссык-Куль', 'г. Чолпон-Ата; точный адрес  в 2ГИС не указан. Координаты 42.644217', NULL, NULL, NULL, 'Кыргызстан, Иссык-Кульская обл., г. Чолпон-Ата; точный адрес (улица/дом) в 2ГИС не указан. Координаты 42.644217, 77.100394 — район ул. Жуман Акималиева, ~430 м юго-западнее санатория «Голубой Иссык-Куль»', 42.644217, 77.100394, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=42.644217,77.100394', 'https://2gis.kg/cholpon-ata/geo/70030076150329771', 'Отдельная гео-точка в 2ГИС, помеченная просто как «Теннисный корт», в центральной части Чолпон-Аты у побережья.', 'Отдельная гео-точка в 2ГИС, помеченная просто как «Теннисный корт», в центральной части Чолпон-Аты у побережья. К карточке привязаны 2 фотографии, но ни названия владельца, ни телефона, ни адреса дома 2ГИС не даёт. По координатам объект находится в курортной зоне на ул. Жуман Акималиева, между территорией санатория «Голубой Иссык-Куль» (42.647386, 77.103279) и берегом.

Скорее всего это корт на территории одного из пансионатов/санаториев курортной зоны Чолпон-Аты (наиболее вероятный кандидат — санаторий «Голубой Иссык-Куль», чей пляж расположен рядом), но привязка НЕ подтверждена. Сезонность: летняя. Состояние неизвестно. Поисковые страницы 2ГИС (search) отдают 500-ю ошибку автоматическим фетчерам, поэтому провести полный обход рубрики «Теннисные корты» по Чолпон-Ате не удалось.', '[{"type": "outdoor", "count": 1, "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Теннисный корт, г. Ош (площадка Osh Open) — офиц. название не установл
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('tennisnyy-kort-osh', 'Теннисный корт, г. Ош (площадка Osh Open) — офиц. название не установлено', NULL, 'Другие регионы', 'ул. Ленинградская', NULL, NULL, NULL, 'г. Ош, ул. Ленинградская (координаты 40.524152, 72.802938)', 40.524152, 72.802938, NULL, NULL, 'https://www.google.com/maps/search/?api=1&query=40.524152,72.802938', 'https://2gis.kg/osh/geo/70030076154243058', 'Единственный подтверждённый теннисный корт в городе Ош по данным 2ГИС и каталога TennisCourtsMap.', 'Единственный подтверждённый теннисный корт в городе Ош по данным 2ГИС и каталога TennisCourtsMap. Именно в Оше с 2024 года Федерация тенниса КР под эгидой ATF проводит международные турниры Osh Open и юниорские соревнования — в 2024 это был первый турнир такого масштаба в Оше за годы независимости. Технические характеристики нигде не публиковались.

Турниры проходят в конце апреля — начале мая, значит корт открытый и сезонный. В 2ГИС числится как гео-объект, а не организация — карточки с телефоном и ценами нет. Существует минимум с 2013 года. Привязка Osh Open к этому корту — обоснованный вывод, но прямо ни одна публикация площадку не называет. Организатор — директор теннисной школы Назар Каракожоев.', '[{"type": "outdoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- ФОК «Газпром» Джалал-Абад
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('fok-gazprom-dzhalal-abad', 'ФОК «Газпром» Джалал-Абад', NULL, 'Другие регионы', 'ул. Даниэлбека Малашова', '53/1', NULL, NULL, 'Джалал-Абадская обл., г. Джалал-Абад, ул. Даниэлбека Малашова, 53/1', NULL, NULL, '+996 372 22 52 38', NULL, NULL, 'https://2gis.kg/dzhalal-abad/firm/70000001084005071', 'Физкультурно-оздоровительный комплекс, построенный «Газпромом» по программе «Газпром — детям» и открытый в ноябре 2018 года, девятый такой объект в Кыргызстане.', 'Физкультурно-оздоровительный комплекс, построенный «Газпромом» по программе «Газпром — детям» и открытый в ноябре 2018 года, девятый такой объект в Кыргызстане. Площадь около 2 500 м², пропускная способность свыше 300 человек в день. В сообщении об открытии прямо указано, что зал предназначен в том числе для тренировок и соревнований по теннису. Работает ежедневно 09:00–24:00.

Услуги: Универсальный зал: баскетбол, волейбол, мини-футбол, бокс, вольная борьба, дзюдо, самбо, джиу-джитсу, настольный теннис; аренда поля; оплата по QR; пандус и доступный вход

ВАЖНО: это универсальный игровой зал, а не специализированный теннисный корт — теннис здесь, по всей видимости, реализован разметкой площадки. Отдельных фото корта и данных о покрытии нет. Нужен звонок, чтобы подтвердить большой теннис, а не только настольный. Карточка 2ГИС оформлена на ОО «Ассоциация футбола Жалал-Абадской области».', '[{"type": "indoor", "count": "", "surface": "", "price": "", "partner": false}]'::jsonb, false, false, 0);

-- Теннисный корт, с. Отуз-Адыр (Ошская обл.)
INSERT INTO courts (id, name, name_en, city, street, building, district, postal_code, address, lat, lng, phone, email, google_maps_url, twogis_url, short_desc, description, court_types, partner, promoted, rating) VALUES
  ('tennisnyy-kort-otuz-adyr', 'Теннисный корт, с. Отуз-Адыр (Ошская обл.)', NULL, 'Другие регионы', 'с. Отуз-Адыр', NULL, NULL, NULL, 'Ошская область, с. Отуз-Адыр (точный адрес в источнике не указан)', NULL, NULL, NULL, NULL, NULL, NULL, 'Объект категории «теннисный корт» в Яндекс.Картах в селе Отуз-Адыр Ошской области.', 'Объект категории «теннисный корт» в Яндекс.Картах в селе Отуз-Адыр Ошской области. Карточка практически пустая: нет телефона, режима работы, фотографий и отзывов. Единственный найденный теннисный объект в Ошской области за пределами города Ош.

Карточка не заполнена и не подтверждена независимым источником; возможно, это школьная или сельская площадка. Требуется проверка на месте.', '[]'::jsonb, false, false, 0);

